import{_ as t,o as s,c as r,ah as a}from"./chunks/framework.BsNNkeaH.js";const g=JSON.parse('{"title":"Leave requests","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/conges.md","filePath":"src/en/guide/conges.md"}'),o={name:"en/guide/conges.md"};function n(i,e,d,l,h,u){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="leave-requests" tabindex="-1">Leave requests <a class="header-anchor" href="#leave-requests" aria-label="Permalink to &quot;Leave requests&quot;">​</a></h1><p>Leave is one of the few parts of ERA that doesn&#39;t depend on your role: <strong>every staff member</strong> files their own requests, whether they teach, run the cash desk, the infirmary or the boarding house. Only the decision is reserved for the school&#39;s administration.</p><h2 id="filing-a-request" tabindex="-1">Filing a request <a class="header-anchor" href="#filing-a-request" aria-label="Permalink to &quot;Filing a request&quot;">​</a></h2><p>From <strong>My leave requests</strong>:</p><ol><li>Pick the <strong>type</strong>: paid leave, unpaid leave or sick leave.</li><li>Set the <strong>start date</strong> and <strong>end date</strong>.</li><li>Write the <strong>reason</strong>.</li><li>Click <strong>Submit request</strong>.</li></ol><p>The request is created as <strong>Pending</strong>. There&#39;s nothing else to do: it appears in the administration&#39;s own queue.</p><h2 id="following-your-requests" tabindex="-1">Following your requests <a class="header-anchor" href="#following-your-requests" aria-label="Permalink to &quot;Following your requests&quot;">​</a></h2><p>The <strong>History</strong> section of the same page lists your past and current requests with their status:</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td>Pending</td><td>Filed, not reviewed yet</td></tr><tr><td>Approved</td><td>Granted by the administration</td></tr><tr><td>Rejected</td><td>Refused — the rejection reason is shown with the request</td></tr></tbody></table><p>You only ever see your own requests, never a colleague&#39;s.</p><div class="tip custom-block"><p class="custom-block-title">Filing isn&#39;t open to everyone</p><p>This page assumes you have a staff record at the school. An account without one (a parent, a student) has no access to it — see <a href="/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a> for how records are created.</p></div><h2 id="deciding-on-requests-administration" tabindex="-1">Deciding on requests (administration) <a class="header-anchor" href="#deciding-on-requests-administration" aria-label="Permalink to &quot;Deciding on requests (administration)&quot;">​</a></h2><p>An administrator gets an extra view, <strong>Leave requests</strong>, listing requests from <strong>all</strong> staff.</p><p>For each request:</p><ul><li><strong>Approve</strong> grants it immediately.</li><li><strong>Reject</strong> opens a confirmation dialog asking for a <strong>rejection reason</strong>. That reason is then visible to the person concerned in their own history — which is what saves them from having to come and ask why.</li></ul><p>An already-decided request stays in the list with its outcome: the history is a record, nothing is erased.</p>',16)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
